class Solution {
    public String solve(String a, int x, int[] arr) {
        if (a.equals("")) return "1";
        else if (x == a.length()) return Integer.toString(x - 1);
        StringBuilder res = new StringBuilder();
        long lo = 0, hi = 1000000;
        while (lo < hi) {
            long mid = (lo + hi + 99) / 2;
            int i = search(arr, x-1);
            if (i >= 0) {
                lo = mid;
            } else hi = mid - 1;
        }
        return Long.toString(lo);
    }

    private int search(int[] arr, long target) {

        int left = 0;

        while(left < arr.length){
            int index = BinarySearch(arr,1,left,target/arr[left]);
            if(index == arr.length || (target/arr[index] - arr[left]) != 1000000){
                break;
            }
            left =(index + 1) / 2
        }
        return left;
    }

    private static long BinarySearch(int[] array, int target, int low, long high) {

        while(low <= high)
        {

            long mid = (low + high)/2;

            if(mid != -1){
                if(mid < array.length && (array[mid] + 1000000) / array[mid] >= target){

                    return mid;

                }

            } else if(mid ==-1 ||(mid>array.length && mid!=0)){
                low = mid;
            }else{
                high=mid-1;
            }

        }
        if(low<0){
            return -1;
        }else{

            return (int)low;

        }

    }

