    P.extend(range(N, 2*N - 1))
    Ans = [-1]*N
    C = collections.deque([(A[0],0)])
    j = bisect_left(P, N)
    for m in range(M):
        if C and len(C) >= j:
            idx, time = C.popleft()
            if(time > m + 1):
                Ans[idx - 1] = time
            else:
                P[idx] = 0
                while C and len(C) >= j:
                    idx, time = C.popleft()
                    if(time < m + 1):
                        Ans[idx - 1] = time
                C.append((P[j],j))
        elif A[m] == N+j-1:
            for i in range(j-1, -1, -1):
                P[i] = j
            j -= len(C)
            C.clear()
    print(*Ans)

