def decode_string(s):
    stack = []
    for i in range(len(s)):
        if int(s[i]) > 0:  # two digits was found, add it to the previous number
            if not stack:
                stack.append "")
            else:
                temp = ""
                while True:
                    temp += stack.pop()
                    num = int(temp)
                    next_num = "" + str(num * 10) if i == len(s) - 1 else str(int(temp[0]) + num)
                    if next_num > s[i]:
                        break
                stack.append(next_num)
        elif s[i] != " ":  # one digit was found, append it to the result
            stack[-1] += s[i]
    return "".join(stack)

